exact_definitions.PqxdhDeploymentPublishedTuple.ownerIdent:
def ownerIdentities (setup : Setup baseSpec KemSK) (native : PqxdhRegistrationSchedule.State KemSK) :
    List PqxdhEd25519EufCma.Ed25519PublicKey :=
  native.owners.map fun owner => (setup.joint.publicKeys owner.beacon.identity).ed25519

exact_definitions.PqxdhDeploymentRecordKernels.PeerStep:
def PeerStep (c : Pqxdh.Crypto) (before after : RawCtxServerRouting.Server Unit Unit) : Prop :=
  ∀ kid, peerKernel after kid = peerKernel before kid ∨
    (peerKernel before kid = none ∧ ∃ kernel, peerKernel after kid = some kernel ∧ Live c kernel)
